export type Order = { "active_payment_attempt"?: OrderPaymentAttempt; "applied_discounts"?: Array<AppliedDiscount>; "authorization_amounts"?: OrderAuthorizationAmounts; /** What the buyer can do with the order, in this order: start_return, then resend_receipt. A buyer's read through a customer session on /v1/me, or in Flint's buyer account, lists both every time; a merchant read gets an empty list. A list of orders leaves start_return out, since only a read of one order checks return eligibility. start_return is due when the last open return window ends. Example: []. */ "buyer_actions": Array<BuyerAction>; /** Email and phone saved when payment started, from the pay request's buyer_contact or the paying checkout session's saved contact. It does not change the linked customer. */ "buyer_contact"?: CheckoutBuyerContact; "buyer_note"?: string; "charges"?: Array<OrderCharge>; "checkout_session_ids"?: Array<string>; /** The note supplied when the order was closed. It is not shown to the buyer. */ "closed_reason"?: string; /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; "customer"?: (({ /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; "customer_id": string; "email": string; "name"?: string; "phone"?: string; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; }) | (null)); "customer_id"?: string; /** The shipment or local-delivery destination committed for this order. Payment freezes this value; fulfillment recipient changes do not replace it. Omitted for a checkout session credential that doesn't act for the customer the buyer verified. */ "delivery_destination"?: OrderDeliveryDestination; /** Caller-owned identifier for this resource in an external system. maxLength: 255. */ "external_reference_id"?: string; "fulfillment_status"?: "not_fulfilled" | "partially_fulfilled" | "fulfilled" | "canceled" | "not_applicable" | "closed" | (string & {}); "fulfillments"?: Array<Fulfillment>; "gift_card_estimate"?: OrderGiftCardEstimate; "gift_card_settlements"?: Array<OrderGiftCardSettlement>; "gift_card_tender_enabled"?: boolean; "gift_cards"?: Array<OrderGiftCardSelection>; "internal_note"?: string; "inventory_exception_status"?: "paid_inventory_failed" | "resolved" | (string & {}); /** The reservation holding stock for this order, when one exists. */ "inventory_reservation_id"?: string; /** Where this order's tracked demand is routed. Required before an order containing tracked variants can hold stock. */ "inventory_routing_source"?: InventoryRoutingSource; "line_items": Array<OrderLineItem>; "merchant_id"?: string; "metadata"?: Record<string, string>; "order_id": string; "order_number"?: string; /** Use an exact numeric string, not a floating-point number. Format: int64. */ "order_revision"?: string; "origin"?: "virtual_terminal" | "payment_link" | "checkout" | "api" | "subscription" | (string & {}); "payment_collection"?: PaymentCollection; "payment_intent_ids"?: Array<string>; "payment_intents"?: Array<ExpandedPaymentIntentSummary>; "payment_status": "unpaid" | "partially_paid" | "paid" | (string & {}); "pricing_amounts": PricingAmounts; "purchased_event"?: PurchasedEvent; "refund_ids"?: Array<string>; "refund_status": "none" | "partially_refunded" | "refunded" | (string & {}); "requested_tip"?: RequestedTip; /** Value applied to this order from items the buyer returned, such as an exchange's replacement order. Included in settlement_amounts.paid_money. */ "return_credit_settlements"?: Array<OrderReturnCreditSettlement>; "settlement_amounts": SettlementAmounts; "setup_collection"?: PaymentCollection; "status": "open" | "closed" | (string & {}); "subscription"?: (({ /** Format: int32. */ "billing_anchor_day": number; "cancel_at_period_end": boolean; /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; "current_period_end"?: string; "current_period_start"?: string; "customer_id": string; /** RFC3339 timestamp. Format: date-time. */ "next_billing_at"?: string; "status": "trialing" | "active" | "paused" | "past_due" | "canceled" | "incomplete" | (string & {}); "subscription_id": string; "subscription_plan_id": string; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; }) | (null)); "subscription_id"?: string; "subscription_plan"?: (({ "billing_interval": "daily" | "weekly" | "monthly" | "yearly" | (string & {}); /** Format: int32. */ "billing_interval_count": number; /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; /** ISO 4217 currency code. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; "description"?: string; "line_items"?: Array<SubscriptionPlanLineItem>; "name": string; "setup_fee_money"?: MoneyValue; "status": "active" | "archived" | (string & {}); "subscription_plan_id": string; /** Format: int32. */ "trial_period_days"?: number; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; }) | (null)); "subscription_plan_id"?: string; "tax": OrderTax; "tips"?: Array<Tip>; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; };
